public int compare(anytype o1, anytype o2)
{
    GUPPriceEngineAbstractDecoratedLine obj1 = o1;
    GUPPriceEngineAbstractDecoratedLine obj2 = o2;
    Price price1;
    Price price2;
    if (obj1 is GUPPriceEngineDecoratedPriceLine)
    {
        price1 = (obj1 as GUPPriceEngineDecoratedPriceLine).parmPrice();
        price2 = (obj2 as GUPPriceEngineDecoratedPriceLine).parmPrice();
    }
    else
    {
        price1 = (obj1 as GUPPriceEngineDecoratedAdjustmentValueLine).parmComputedPrice();
        price2 = (obj2 as GUPPriceEngineDecoratedAdjustmentValueLine).parmComputedPrice();
    }

    // Sort by priority in descending order.
    if (obj1.parmJournalLine().parmAggrLinePriority() > obj2.parmJournalLine().parmAggrLinePriority())
    {
        return -1;
    }
    else if (obj1.parmJournalLine().parmAggrLinePriority() < obj2.parmJournalLine().parmAggrLinePriority())
    {
        return 1;
    }
    else
    {
        // Sort by price in ascending order.
        if (price1 > price2)
        {
            return 1;
        }
        else if (price1 < price2)
        {
            return -1;
        }
    }

    return 0;
}
